const crypto = require('crypto');
const fs = require('fs/promises');
const path = require('path');
const db = require('../config/db');

const MAX_RESUME_BYTES = 5 * 1024 * 1024;

function storageRoot() {
  // Storage is outside the public frontend. Deployments may override this with
  // an absolute, private volume path via RESUME_STORAGE_DIR.
  return path.resolve(process.env.RESUME_STORAGE_DIR || path.resolve(__dirname, '../../storage/resumes'));
}

function storagePath(storageKey) {
  // Never accept a client-supplied path. The key is generated by this server.
  if (typeof storageKey !== 'string' || !/^[0-9a-f-]{36}\.pdf$/i.test(storageKey)) {
    throw new Error('Invalid stored resume key.');
  }
  const root = storageRoot();
  const filePath = path.resolve(root, storageKey);
  if (!filePath.startsWith(root + path.sep)) throw new Error('Invalid stored resume path.');
  return filePath;
}

function cleanOriginalName(name) {
  const portable = String(name || 'resume.pdf').replace(/\\/g, '/');
  const basename = path.posix.basename(portable).replace(/[\u0000-\u001f\u007f]/g, '');
  const safe = basename.replace(/[^\w. ()-]/g, '_').trim().slice(0, 255);
  return safe && safe.toLowerCase().endsWith('.pdf') ? safe : 'resume.pdf';
}

function hasPdfSignature(buffer) {
  return Buffer.isBuffer(buffer) && buffer.length >= 5 && buffer.subarray(0, 5).toString('ascii') === '%PDF-';
}

async function removeStoredFile(storageKey) {
  if (!storageKey) return;
  try { await fs.unlink(storagePath(storageKey)); }
  catch (err) { if (err.code !== 'ENOENT') console.error('[resume] Could not remove old resume file:', err.message); }
}

async function selectCurrentResume(userId) {
  const [rows] = await db.promise().query(
    `SELECT id, user_id, original_name, mime_type, file_size, created_at, updated_at
       FROM student_resumes WHERE user_id = ? LIMIT 1`,
    [userId],
  );
  return rows[0] || null;
}

exports.getCurrentResume = async (req, res) => {
  res.set('Cache-Control', 'private, no-store, max-age=0');
  try {
    const resume = await selectCurrentResume(req.user.id);
    return res.status(200).json({ resume });
  } catch (err) {
    console.error('[getCurrentResume] DB error:', err.message);
    return res.status(500).json({ error: 'Failed to load resume details.' });
  }
};

exports.uploadCurrentResume = async (req, res) => {
  res.set('Cache-Control', 'private, no-store, max-age=0');
  if (!req.file) return res.status(400).json({ error: 'Choose a PDF resume to upload.' });
  if (!hasPdfSignature(req.file.buffer)) {
    return res.status(400).json({ error: 'The file does not have a valid PDF signature.' });
  }
  if (req.file.size > MAX_RESUME_BYTES) {
    return res.status(413).json({ error: 'Resume must be 5 MB or smaller.' });
  }

  const userId = req.user.id;
  const newKey = `${crypto.randomUUID()}.pdf`;
  const originalName = cleanOriginalName(req.file.originalname);
  const sha256 = crypto.createHash('sha256').update(req.file.buffer).digest('hex');
  const newPath = storagePath(newKey);
  let previousKey = null;
  let newFileWritten = false;
  let databaseSaved = false;

  try {
    const [oldRows] = await db.promise().query(
      'SELECT storage_key FROM student_resumes WHERE user_id = ? LIMIT 1', [userId],
    );
    previousKey = oldRows[0]?.storage_key || null;

    await fs.mkdir(storageRoot(), { recursive: true, mode: 0o700 });
    await fs.writeFile(newPath, req.file.buffer, { flag: 'wx', mode: 0o600 });
    newFileWritten = true;

    await db.promise().query(
      `INSERT INTO student_resumes (user_id, original_name, storage_key, mime_type, file_size, sha256)
       VALUES (?, ?, ?, 'application/pdf', ?, ?)
       ON DUPLICATE KEY UPDATE
         original_name = VALUES(original_name),
         storage_key = VALUES(storage_key),
         mime_type = VALUES(mime_type),
         file_size = VALUES(file_size),
         sha256 = VALUES(sha256),
         updated_at = CURRENT_TIMESTAMP`,
      [userId, originalName, newKey, req.file.size, sha256],
    );
    databaseSaved = true;

    // Delete the previous private file only after the database points at the
    // replacement. If the write or database operation fails, keep the old one.
    if (previousKey && previousKey !== newKey) await removeStoredFile(previousKey);

    const resume = await selectCurrentResume(userId);
    return res.status(previousKey ? 200 : 201).json({
      message: previousKey ? 'Resume replaced successfully.' : 'Resume uploaded successfully.',
      resume,
    });
  } catch (err) {
    if (newFileWritten && !databaseSaved) await removeStoredFile(newKey);
    console.error('[uploadCurrentResume] Error:', err.message);
    return res.status(500).json({ error: 'Resume upload failed. Please try again.' });
  }
};

async function sendResumeForStudent(studentId, res) {
  const [rows] = await db.promise().query(
    'SELECT original_name, storage_key, file_size FROM student_resumes WHERE user_id = ? LIMIT 1',
    [studentId],
  );
  if (!rows.length) return res.status(404).json({ error: 'No resume has been uploaded yet.' });

  const metadata = rows[0];
  let contents;
  try { contents = await fs.readFile(storagePath(metadata.storage_key)); }
  catch (err) {
    if (err.code === 'ENOENT') return res.status(404).json({ error: 'The stored resume file is missing. Please upload it again.' });
    throw err;
  }

  const downloadName = cleanOriginalName(metadata.original_name).replace(/["\\]/g, '_');
  res.set({
    'Content-Type': 'application/pdf',
    'Content-Length': String(contents.length),
    'Content-Disposition': `attachment; filename="${downloadName}"; filename*=UTF-8''${encodeURIComponent(downloadName)}`,
    'X-Content-Type-Options': 'nosniff',
    'Cache-Control': 'private, no-store, max-age=0',
    'Pragma': 'no-cache',
  });
  return res.status(200).send(contents);
}

exports.downloadCurrentResume = async (req, res) => {
  try {
    return await sendResumeForStudent(req.user.id, res);
  } catch (err) {
    console.error('[downloadCurrentResume] Error:', err.message);
    return res.status(500).json({ error: 'Resume download failed. Please try again.' });
  }
};

exports.downloadApplicantResume = async (req, res) => {
  const studentId = Number(req.params.studentId);
  if (!Number.isSafeInteger(studentId) || studentId <= 0) {
    return res.status(400).json({ error: 'Student ID must be a positive integer.' });
  }

  try {
    if (req.user.role === 'student' && studentId !== Number(req.user.id)) {
      return res.status(403).json({ error: 'Students can only download their own resume.' });
    }

    if (req.user.role === 'company') {
      const [relationship] = await db.promise().query(
        `SELECT 1 AS authorized
           FROM applications a
           JOIN jobs j ON j.id = a.job_id
          WHERE a.student_id = ?
            AND (j.company_id = ? OR (j.posting_source = 'company' AND j.created_by = ?))
          LIMIT 1`,
        [studentId, req.user.id, req.user.id],
      );
      if (!relationship.length) {
        return res.status(403).json({ error: 'Resume access is limited to students who applied to your job postings.' });
      }
    }

    // Placement Cell administrators may access student resumes for legitimate
    // placement administration. Companies must have an application relationship.
    return await sendResumeForStudent(studentId, res);
  } catch (err) {
    console.error('[downloadApplicantResume] Error:', err.message);
    return res.status(500).json({ error: 'Resume download failed. Please try again.' });
  }
};

exports.deleteCurrentResume = async (req, res) => {
  res.set('Cache-Control', 'private, no-store, max-age=0');
  try {
    const [rows] = await db.promise().query(
      'SELECT storage_key FROM student_resumes WHERE user_id = ? LIMIT 1', [req.user.id],
    );
    if (!rows.length) return res.status(404).json({ error: 'No resume has been uploaded yet.' });

    await db.promise().query('DELETE FROM student_resumes WHERE user_id = ?', [req.user.id]);
    await removeStoredFile(rows[0].storage_key);
    return res.status(200).json({ message: 'Resume deleted successfully.' });
  } catch (err) {
    console.error('[deleteCurrentResume] Error:', err.message);
    return res.status(500).json({ error: 'Resume deletion failed. Please try again.' });
  }
};

exports.MAX_RESUME_BYTES = MAX_RESUME_BYTES;
